// Run after editing views/*.html or data/watches.json:   node tools/bundle.js
// It writes js/views-bundle.js and js/fallback-data.js so the site also works when index.html is opened by double-click.
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const views = {};
// Every view must end with this comment. VS Code "Live Server" pastes its reload script before the first </body>
// (or before every </svg> if there is none), which cuts the file short. The marker makes it paste at the very end.
const MARKER = '<!-- </body> (keeps VS Code Live Server from cutting this file short; leave it as the last line) -->';
fs.readdirSync(path.join(root, 'views')).filter(f => f.endsWith('.html')).forEach(f => {
  const file = path.join(root, 'views', f);
  let text = fs.readFileSync(file, 'utf8');
  if (!text.includes('</body>')) { text = text.replace(/\s*$/, '\n\n') + MARKER + '\n'; fs.writeFileSync(file, text); console.log('added Live Server marker to', f); }
  views['views/' + f] = text;
});
fs.writeFileSync(path.join(root, 'js', 'views-bundle.js'), '/* generated by tools/bundle.js - do not edit */\nwindow.AW_VIEWS = ' + JSON.stringify(views) + ';\n');
const data = JSON.parse(fs.readFileSync(path.join(root, 'data', 'watches.json'), 'utf8'));
fs.writeFileSync(path.join(root, 'js', 'fallback-data.js'), '/* generated by tools/bundle.js - do not edit */\nwindow.AW_FALLBACK_DATA = ' + JSON.stringify(data) + ';\n');
console.log('bundled', Object.keys(views).length, 'view(s) and the data file');
